INSERT INTO game (name, price, description, genre, categories, hardware_requirements, released_at) VALUES
('Neon Abyss Drifters', 24.99, 'A vertical-slice roguelike set inside a collapsing arcology where gravity was sold off to creditors. You pilot a magnetic skiff down 900 floors of neon service shafts, scavenging parts from dead couriers and rebuilding your rig between runs. Every death permanently rewrites one district of the tower, so the map you memorize today is the map that betrays you tomorrow.', 'roguelike, action, racing', 'singleplayer, procedural generation, permadeath, controller support', 'potato pc without gpu, but the potato must be angry', '2021-04-16 09:00:00+00'),
('Mossgrave Chronicle', 39.99, 'A slow-burning tactical RPG about four gravediggers who discover that the dead in their valley refuse to stay buried because someone keeps paying them to come back. Combat is turn-based on a hex grid where terrain rots in real time, turning solid ground into sucking bog over four rounds. The story branches on who you choose to bury properly and who you leave for the crows.', 'rpg, strategy, tactical', 'singleplayer, story rich, turn-based, choices matter', '8 GB RAM, dedicated GPU with 4 GB VRAM, and a strong opinion about shovels', '2020-10-02 12:00:00+00'),
('Turbo Gasket Rally', 14.50, 'An arcade rally sim where every car is held together by duct tape and legal ambiguity. Tracks are generated from real topographic data of places that do not exist, and your codriver reads pace notes in a language you slowly learn over 60 stages. Break a gasket mid-stage and you finish the run in limp mode, engine screaming, points bleeding out.', 'racing, simulation, arcade', 'singleplayer, multiplayer, split screen, leaderboards', 'temple os required (we are not joking, we ported it)', '2022-06-11 15:30:00+00'),
('The Quiet Cartographer', 19.99, 'You are the last surveyor employed by a bankrupt empire, sent to map an archipelago that has never held still. There is no combat: you walk, sketch, triangulate, and submit reports that nobody reads. Islands drift between sessions, and the game quietly tracks whether your maps were honest or merely convenient.', 'adventure, simulation, exploration', 'singleplayer, relaxing, no combat, atmospheric', 'any laptop from the last decade, plus one quiet afternoon', '2023-02-28 08:00:00+00'),
('Bonecradle', 0.00, 'A free horror vignette lasting roughly ninety minutes, set in a maternity ward that was evacuated in 1961 and never formally closed. You have one flashlight with a winding crank and no way to run. The building remembers the order you visited its rooms and rearranges itself to make sure you never repeat a route.', 'horror, adventure, psychological', 'singleplayer, free to play, short, first person', 'integrated graphics fine, but headphones mandatory or you will miss everything', '2024-10-31 21:00:00+00'),
('Pixel Butcher Deluxe', 9.99, 'A deliberately grimy 2D beat em up about a cleaver-wielding butcher defending his shop from a hostile takeover by a meal-kit startup. Twelve stages, each ending in a boss fight against a different member of the board. Combos are built from actual butchery techniques, which the game explains in an unsettlingly educational codex.', 'action, beat em up, arcade', 'singleplayer, local co-op, pixel art, gore', 'potato pc without gpu, ideally a russet', '2019-08-20 11:00:00+00'),
('Orbital Tea Company', 27.00, 'A logistics management game where you run a tea import business across nine inhabited moons with wildly incompatible customs regimes. Freight takes real orbital transfer time, so a shipment launched today arrives eleven in-game weeks later into a market that may have collapsed. Success is less about profit and more about surviving your own optimistic forecasts.', 'strategy, simulation, management', 'singleplayer, economy, sandbox, moddable', '4 GB RAM, any GPU, and patience measured in geological units', '2022-01-18 10:00:00+00'),
('Rustfang Hollow', 34.99, 'An open-world survival game set in a boreal forest where the wildlife has been quietly replacing its own bones with scrap metal. You build shelter, trap, smoke meat, and try to understand why the deer are magnetic. There is no tech tree, only recipes you find scratched into things that were not supposed to be writing surfaces.', 'survival, horror, open world', 'singleplayer, crafting, base building, atmospheric', '16 GB RAM recommended; runs on 8 GB if you promise not to look at the trees', '2021-11-05 14:00:00+00'),
('Vector Saint', 7.99, 'A pure twin-stick shooter rendered entirely in glowing wireframe, with a soundtrack that reacts to your accuracy rather than your score. Thirty waves, no upgrades, no unlocks, no story. The only progression is the one happening in your hands.', 'shooter, arcade, action', 'singleplayer, twin stick, high score, controller support', 'literally anything with a screen, including a smart fridge (unsupported but it works)', '2020-03-09 16:00:00+00'),
('Grandma''s Last Dungeon', 22.50, 'A cozy dungeon crawler in which a retired adventurer must clear one final labyrinth to recover her late husband''s pension paperwork. Turn-based, forgiving, and structured around tea breaks that restore health and advance the conversation with the skeletons who now staff the dungeon. Every enemy can be resolved by combat, bribery, or a sufficiently good argument.', 'rpg, adventure, casual', 'singleplayer, turn-based, cozy, story rich, humor', 'potato pc without gpu; grandma plays it on a 2009 netbook and beat it twice', '2023-05-14 13:00:00+00'),
('Hyperlane Auditors', 44.99, 'A 4X grand strategy title where you play not as an empire but as the interstellar accounting bureau that audits them. You never build a fleet; you approve, delay, or deny the budgets of seven AI civilizations locked in a war you are technically neutral about. Deny the wrong line item and a species goes extinct in the quarterly report.', 'strategy, 4x, simulation', 'singleplayer, grand strategy, turn-based, political', '8 GB RAM, mid-range GPU, and a tolerance for spreadsheets that scream', '2022-09-27 10:00:00+00'),
('Swamp Logic', 12.99, 'A first-person puzzle game about draining a bayou using a network of pumps, sluices, and one increasingly unreliable intern. Water simulation is the entire puzzle mechanic, and every solution permanently alters the terrain for the rest of the campaign. Forty-two chapters, no hints, one undo button that costs you an hour of in-game time.', 'puzzle, simulation, first person', 'singleplayer, physics, difficult, no hand holding', 'needs a GPU that can do fluid sim, so not a potato this time, sorry', '2024-03-21 09:00:00+00'),
('Kettle Knights', 16.99, 'A four-player brawler in which knights fight exclusively with kitchenware inside a castle kitchen that is always thirty seconds from catching fire. Weapons degrade into cookware, then into scrap, then into seasoning. The last knight standing has to actually finish cooking the meal, which is where most matches are truly lost.', 'action, party, fighting', 'multiplayer, local co-op, online co-op, humor, controller support', 'four controllers and one friend who is not allowed near the stove in real life', '2021-07-30 17:00:00+00'),
('Null Pointer Exception: The Game', 4.99, 'A programming puzzle game disguised as a haunted house, where each room is a memory segment and the ghosts are dangling references. You write short scripts in a purpose-built language to free the trapped processes without corrupting the heap. The final act is a single room containing a bug that the developers have publicly admitted they cannot reproduce.', 'puzzle, programming, horror', 'singleplayer, education, difficult, indie', 'any machine that can run a text editor and hold a grudge', '2023-09-13 20:00:00+00'),
('Saltmarch', 29.99, 'A narrative survival game about a caravan of salt traders crossing a dried inland sea over the course of one hundred in-game days. Resources are scarce, the route is fixed, and every companion has a reason to want the caravan to stop somewhere specific. Nobody dies of thirst in this game; they die of consensus.', 'survival, adventure, rpg', 'singleplayer, story rich, resource management, choices matter', '6 GB RAM, integrated graphics acceptable, water bottle recommended', '2022-04-08 12:00:00+00'),
('Chrome Larks', 11.00, 'A short flight game about mechanical birds delivering mail across a country that stopped existing during the last war. Controls are deliberately floaty and wind is modeled honestly, so most of the challenge is landing rather than flying. Twenty-six letters, twenty-six routes, one ending that depends on whether you read the mail.', 'adventure, simulation, flight', 'singleplayer, relaxing, short, atmospheric, story rich', 'mid-range anything; runs beautifully on a laptop, badly on a desktop, we do not know why', '2020-12-01 08:30:00+00'),
('Deepwell Sanitation Corps', 18.99, 'Co-op horror maintenance sim for up to three players who clean the filtration systems beneath a city that is legally not allowed to know what is down there. Objectives are mundane: unclog, replace, log, exit. The horror comes entirely from the fact that the logs from previous shifts are readable and written in your handwriting.', 'horror, simulation, co-op', 'multiplayer, online co-op, first person, atmospheric', '8 GB RAM, dedicated GPU, and voice chat with people you trust to not scream', '2024-06-19 19:00:00+00'),
('Paper Tiger Tactics', 21.99, 'A turn-based tactics game where every unit is an origami construct that unfolds when damaged, revealing the orders written inside. Reading a destroyed enemy tells you the opposing commander''s intent for the next three turns. Losing units is therefore an intelligence operation, which makes the difficulty curve extremely strange in the best way.', 'strategy, tactical, puzzle', 'singleplayer, turn-based, hex grid, difficult', 'low spec friendly, runs on a thin client and a prayer', '2023-11-07 10:00:00+00'),
('Voidgrass', 8.49, 'A minimalist farming game set on a plateau floating in absolute darkness, where crops grow toward a light source that moves unpredictably. There are no seasons, no neighbors, and no market; you farm because the plateau shrinks when you do not. Roughly fifteen hours long and steadily, quietly unsettling.', 'simulation, farming, horror', 'singleplayer, relaxing, atmospheric, minimalist', 'potato pc without gpu, but the potato is planted and it is growing', '2021-02-14 07:00:00+00'),
('Muffin Tectonics', 5.99, 'A physics puzzler about baking on an unstable continental plate. Each level gives you an oven, a recipe, and an earthquake schedule you must work around. Later levels introduce a rival bakery on the opposing plate whose success directly causes your seismic events.', 'puzzle, physics, casual', 'singleplayer, humor, short sessions, family friendly', 'runs on anything, including the tablet you keep in the kitchen with flour in the ports', '2022-11-22 11:00:00+00'),
('The Ninth Ledger', 31.99, 'A detective game set in a merchant city where all crimes are financial and all evidence is bookkeeping. You interview nobody; you read ledgers, cross-reference dates, and file accusations that can ruin innocent houses. Six cases, each solvable in multiple ways, only one of which is also correct.', 'adventure, detective, puzzle', 'singleplayer, story rich, investigation, text heavy, choices matter', 'any machine, any decade, plus reading glasses if you are honest with yourself', '2023-07-25 09:00:00+00'),
('Ashbind Requiem', 49.99, 'A large action RPG set two hundred years after a magical industry collapse, where spellcasting is a regulated trade and unlicensed casters are hunted by former colleagues. Combat mixes stamina-based melee with a spell system built from reagents you physically carry, so your loadout is also your weight limit. Roughly sixty hours, with a New Game Plus that changes who is hunting whom.', 'rpg, action, open world', 'singleplayer, souls-like, story rich, character customization', '16 GB RAM, GPU with 8 GB VRAM, SSD strongly recommended unless you enjoy elevators', '2024-02-09 15:00:00+00'),
('Forklift Certified', 13.99, 'A warehouse simulator that takes forklift operation with total sincerity and everything else with none. Full load physics, pallet stacking, and an OSHA-adjacent certification exam that unlocks the campaign. The narrative emerges from the increasingly deranged shipping manifests you are asked to fulfill.', 'simulation, comedy, sandbox', 'singleplayer, multiplayer, physics, humor, sandbox', 'mid-range PC; forklift not included but genuinely would help', '2021-09-16 13:00:00+00'),
('Static Choir', 26.50, 'A rhythm horror game in which you conduct a choir of radio signals picked up from abandoned broadcast towers. Each level is a song assembled from noise, and mistiming a cue introduces a new voice that stays for the rest of the run. Fifteen towers, and the last one only tunes in if you have been perfect.', 'rhythm, horror, music', 'singleplayer, atmospheric, difficult, headphones recommended', 'modest specs, but a good sound card or decent DAC changes the whole game', '2023-01-27 22:00:00+00'),
('Lanternfall', 17.99, 'A side-scrolling metroidvania set in a mountain where the only light source is a lantern you must periodically leave behind to power mechanisms. Progression is therefore a constant negotiation between where you can see and where you can reach. Hand-drawn, roughly twelve hours, with a map that fills in only what the lantern has actually touched.', 'metroidvania, platformer, adventure', 'singleplayer, hand drawn, exploration, atmospheric', 'low spec friendly, runs on a handheld and looks better there', '2022-03-03 10:00:00+00'),
('Bitrot Barony', 23.00, 'A colony builder where your settlement is stored on failing hardware and sectors of your own save file corrupt over time. Corrupted districts return as garbled versions of themselves, with residents who remember a version of events that never happened. You can repair the data or let the barony become something else entirely.', 'strategy, simulation, city builder', 'singleplayer, base building, sandbox, experimental', '8 GB RAM, and an SSD you are not emotionally attached to', '2024-08-12 11:00:00+00'),
('Cormorant Bay Fisheries', 15.99, 'A commercial fishing sim across four seasons in a cold northern bay, modeled with real tidal and stock-depletion mechanics. Overfish a ground and it stays empty for years of in-game time, which the game never warns you about. There is a full story about the town, but you only see it if you stay solvent long enough to keep visiting the harbor bar.', 'simulation, management, adventure', 'singleplayer, economy, fishing, story rich, realistic', '6 GB RAM, any GPU from the last eight years, waterproof keyboard optional', '2020-06-25 08:00:00+00'),
('Glasswing Protocol', 36.99, 'A stealth game in which you play an industrial saboteur whose suit turns transparent only while you hold your breath. Breath is the entire resource economy: movement, invisibility, and the ability to interact all draw from one shrinking meter. Twenty-two facilities, no weapons, and a scoring system that rates how little evidence you left of having existed.', 'stealth, action, thriller', 'singleplayer, first person, difficult, no combat, immersive sim', '12 GB RAM, dedicated GPU, and lungs (in-game only, please breathe normally)', '2023-04-18 14:00:00+00'),
('Doomsday Bake-Off', 10.99, 'A competitive cooking game set during the final six hours before an unspecified apocalypse, where four contestants race to produce the last dessert ever made. Ingredients degrade rapidly, the studio lights fail on a schedule, and the judges leave one by one. Whoever finishes last still gets scored, which is the joke and also the tragedy.', 'party, cooking, action', 'multiplayer, online co-op, local co-op, humor, short sessions', 'runs on a toaster, thematically appropriate', '2022-12-31 23:00:00+00'),
('Tidebound Heresy', 41.99, 'A naval RPG set in an archipelago where the church has declared the tides themselves heretical and outlawed sailing after dusk. You captain a smuggler brig, balancing a crew whose loyalties shift with each cargo you accept, and navigation is done by hand with a real star chart. Roughly forty hours, with three endings that differ only in who is still aboard when you make landfall.', 'rpg, adventure, naval', 'singleplayer, story rich, exploration, choices matter, crew management', '8 GB RAM, dedicated GPU, and the willingness to learn what a sextant is', '2022-05-19 10:00:00+00'),
('Concrete Gardener', 12.99, 'A slow city-repair game where you plant vegetation into the cracks of an abandoned megablock and wait decades of compressed time for roots to break the structure apart. There is no fail state, only the question of whether the building comes down before your character does. Each playthrough covers sixty in-game years in about nine hours.', 'simulation, relaxing, strategy', 'singleplayer, cozy, atmospheric, sandbox, time management', 'potato pc without gpu, the plants are mostly sprites and we are not ashamed', '2023-03-11 09:00:00+00'),
('Grindhouse Autopilot', 19.99, 'A rail shooter where the rail is a self-driving car that has decided on a route you strongly disagree with. You cannot steer, only shoot, and the car narrates its reasoning in a calm voice that becomes progressively less calm. Eight chapters, one continuous drive, no checkpoints after chapter five.', 'shooter, action, arcade', 'singleplayer, rail shooter, humor, difficult, controller support', 'mid-range GPU, and a seatbelt for emotional reasons', '2021-10-08 20:00:00+00'),
('Wormtongue Library', 28.99, 'A text-heavy investigation game set in a library where books rewrite themselves to match whatever the reader most wants to believe. You catalogue, cross-check, and eventually have to decide which edition of a historical event to file as canon. Every choice propagates: later books cite the version you filed.', 'adventure, puzzle, detective', 'singleplayer, text heavy, investigation, story rich, choices matter', 'any machine; the hardest requirement is sustained attention', '2024-04-02 11:00:00+00'),
('Slagfist', 16.50, 'A brutal 1v1 fighting game with four characters, no unlockables, and a training mode longer than most campaigns. Every attack has real recovery frames and the block button also drains health, so defense is a resource rather than a state. Competitive scene is tiny, vicious, and extremely welcoming.', 'fighting, action, competitive', 'multiplayer, online pvp, local pvp, difficult, esports', 'low spec friendly; netcode is rollback and better than it has any right to be', '2020-09-04 16:00:00+00'),
('Permafrost Dispatch', 24.50, 'You are a radio dispatcher for an arctic research network, coordinating twelve field teams you never see. Everything happens through voice logs, weather reports, and a map you update by hand. When a team stops responding you have to decide who gets diverted, and the game holds you to it for the rest of the season.', 'simulation, thriller, management', 'singleplayer, story rich, atmospheric, text heavy, choices matter', 'runs on anything, but a second monitor genuinely improves it', '2022-02-17 08:00:00+00'),
('Kaiju Property Damage LLC', 14.99, 'An insurance adjuster simulator set in a city attacked by giant monsters roughly twice a month. You tour the wreckage, assess claims, and determine whether that hole was caused by a covered kaiju event or by ordinary negligence. Surprisingly dense simulation wrapped in a very silly premise.', 'simulation, comedy, puzzle', 'singleplayer, humor, investigation, first person, indie', 'mid-range PC; the destruction meshes are heavier than the jokes', '2023-06-30 13:00:00+00'),
('Nocturne Engine', 33.99, 'A survival horror game aboard a sleeper ship where waking anyone costs oxygen you cannot replace. You are awake, something else is awake, and there are eleven thousand people who could help if you were willing to spend their air. No combat, only routing and terrible arithmetic.', 'horror, survival, thriller', 'singleplayer, first person, atmospheric, resource management, difficult', '12 GB RAM, dedicated GPU, and the ability to do math while frightened', '2024-09-20 22:00:00+00'),
('Feral Orchard', 9.99, 'A small farming game about an orchard where the trees have started making decisions. Pruning is a negotiation, harvests require consent, and the game tracks whether you have been fair to a plant over multiple seasons. About eight hours, deeply strange, unexpectedly gentle.', 'simulation, farming, adventure', 'singleplayer, cozy, atmospheric, short, indie', 'potato pc without gpu; the trees do not need ray tracing to judge you', '2021-05-23 07:00:00+00'),
('Overclock Cathedral', 22.99, 'A puzzle game set inside a computing temple where monks maintain a processor the size of a city. You solve thermal and scheduling problems as devotional rites, and the difficulty comes from the fact that the liturgy is also the documentation. Sixty puzzles, plus a bonus set that requires reading the in-game scripture properly.', 'puzzle, strategy, simulation', 'singleplayer, difficult, programming, atmospheric, no hand holding', 'temple os required (the joke wrote itself, we just shipped it)', '2023-08-08 12:00:00+00'),
('Backroad Taxidermy', 11.99, 'A quiet rural adventure about inheriting your uncle''s taxidermy shop and the mailing list that came with it. You take commissions, drive to pickups, and slowly understand what the regulars are actually preserving. Dialogue-driven, roughly ten hours, with an ending that changes based on which commissions you refused.', 'adventure, narrative, simulation', 'singleplayer, story rich, choices matter, atmospheric, indie', 'low spec friendly; the driving sections are the only thing that will make a fan spin', '2022-08-14 17:00:00+00'),
('Ironroot Siege', 45.00, 'A large-scale RTS about a single fortress under a siege that lasts the entire campaign. You never attack; you allocate, ration, repair, and decide which walls to sacrifice. Thirty scenarios chart one year of encirclement, and the campaign has no victory condition beyond how long the fortress holds and in what shape.', 'strategy, rts, simulation', 'singleplayer, base building, difficult, historical, resource management', '16 GB RAM, dedicated GPU, and a high pain threshold for unit pathing', '2021-12-09 14:00:00+00'),
('Chromatic Aberration', 6.99, 'A short abstract platformer where the three color channels of the screen are separate physical layers you can shift independently. Solid ground in red may be empty air in blue, so movement is a constant act of visual reinterpretation. Ninety levels, no story, extremely precise controls.', 'platformer, puzzle, arcade', 'singleplayer, difficult, minimalist, controller support, speedrun', 'runs on anything with a display; colorblind mode included and it is a whole different game', '2020-11-17 15:00:00+00'),
('Threnody for Spare Parts', 29.99, 'A narrative adventure about a robot repair technician in a scrapyard who keeps finding machines that remember being people. Repairs are a hands-on minigame, but the real game is in the conversations you have while you work. Twelve chapters, around fourteen hours, and it does not resolve cleanly on purpose.', 'adventure, narrative, simulation', 'singleplayer, story rich, sci-fi, emotional, choices matter', '6 GB RAM, integrated graphics acceptable, tissues not included', '2023-10-06 19:00:00+00'),
('Blastfurnace Dating Sim', 13.49, 'You are a metallurgist at a struggling foundry, and all six romance options are other metallurgists with strong incompatible opinions about alloy composition. The relationship system is literally a phase diagram. Genuinely funny, genuinely researched, and the bad ends involve brittleness in both senses.', 'visual novel, simulation, comedy', 'singleplayer, dating sim, humor, story rich, anime', 'any laptop; the phase diagrams are the heaviest asset in the game', '2024-05-16 18:00:00+00'),
('Sunken Ledger', 18.99, 'An underwater exploration game about salvaging a flooded bank district, where every vault you open contains records rather than money. You map the flooded blocks, recover documents, and reconstruct why the city was allowed to drown. Oxygen is generous, darkness is not.', 'adventure, exploration, mystery', 'singleplayer, underwater, atmospheric, story rich, first person', '8 GB RAM, dedicated GPU, and comfort with enclosed spaces', '2022-07-12 10:00:00+00'),
('Hexmarket Bazaar', 7.49, 'A deck-building trading game set in a market where the currency is favors and the favors have expiry dates. You build a deck of contacts, not cards, and every trade permanently removes a contact from the shared pool for all future runs of that save. Short runs, brutal economy, twenty hours to see everything.', 'card game, strategy, roguelike', 'singleplayer, deck building, economy, difficult, replayable', 'potato pc without gpu; it is cards, we are not going to pretend otherwise', '2021-03-26 11:00:00+00'),
('Dead Air Broadcast', 25.99, 'A horror game where you run a late-night radio station in a valley with exactly one listener you cannot identify. Callers phone in, you choose what to air, and the things you broadcast start appearing outside the studio. Five in-game nights, heavy on audio design, extremely light on jumpscares.', 'horror, simulation, narrative', 'singleplayer, atmospheric, psychological, story rich, headphones recommended', 'modest specs; a good pair of headphones matters more than your GPU', '2023-12-15 23:00:00+00'),
('Zero Gravity Plumbing', 15.99, 'A co-op physics game about repairing water systems on a station where every leak becomes a floating sphere that reflows on contact. Two to four players, shared toolkits, and a difficulty curve determined entirely by how badly your team communicates. Fifty jobs plus a freeplay station that can be flooded to the ceiling.', 'simulation, puzzle, co-op', 'multiplayer, online co-op, physics, humor, sandbox', 'mid-range GPU for the fluid sim; four players means four chances for a potato to ruin it', '2022-10-20 16:00:00+00'),
('The Understudy', 20.99, 'A theatre-set mystery where you play a replacement actor who realizes the script has been describing real events in the building. Rehearsals are levels, and memorizing lines unlocks dialogue options with the cast. Three acts, roughly eleven hours, and the final performance is played live with no retries.', 'adventure, mystery, narrative', 'singleplayer, story rich, investigation, choices matter, atmospheric', 'low spec friendly; the theatre is one room and we lit it very carefully', '2024-07-11 20:00:00+00'),
('Rustline Freight', 32.50, 'A freight railway simulator across a decaying continental network, where track maintenance is your responsibility and derailments are permanent to the save. Schedules, weight limits, gradient physics, and a repair budget that never quite covers the year. Around eighty hours of campaign across four regions.', 'simulation, management, strategy', 'singleplayer, trains, economy, realistic, sandbox', '12 GB RAM, dedicated GPU, and genuine enthusiasm for rolling stock', '2021-06-18 09:00:00+00'),
('Screamjar', 3.99, 'A tiny arcade horror game about capturing screams in jars for a client who never explains why. Levels are single rooms, runs are under three minutes, and the difficulty is in identifying which sound is worth the jar. One hundred rooms, no story, surprisingly addictive.', 'horror, arcade, casual', 'singleplayer, short sessions, high score, indie, headphones recommended', 'runs on anything; the audio engine is the only expensive part', '2020-10-13 21:00:00+00'),
('Marrowgrind Depths', 38.99, 'A hardcore dungeon crawler with grid-based movement, full party management, and a hunger system that also applies to your torches. Nine levels down, no map given, and mapping by hand on graph paper is genuinely the intended experience. Honest about being difficult, honest about being slow.', 'rpg, dungeon crawler, horror', 'singleplayer, turn-based, permadeath, difficult, no hand holding', '4 GB RAM, integrated graphics fine, graph paper and a pencil strongly recommended', '2023-02-02 13:00:00+00'),
('Balloon Mortgage', 8.99, 'A satirical management game about running a hot air balloon housing development in a country with no aviation law. Residents drift, rents float, and the entire settlement can be blown across a border overnight. Deliberately absurd, mechanically tight, about twelve hours to clear the campaign.', 'strategy, simulation, comedy', 'singleplayer, city builder, humor, economy, sandbox', 'low spec friendly; the balloons are instanced and cheerfully cheap', '2022-04-27 12:00:00+00'),
('Silent Green Line', 27.99, 'A metro operator sim set on a single circular line that runs through a city that no longer has daylight. You drive, you announce stops, you keep to a schedule, and you learn the regulars by sight. Nothing dramatic happens for the first six hours, which is exactly the point.', 'simulation, atmospheric, narrative', 'singleplayer, first person, relaxing, story rich, realistic', '8 GB RAM, dedicated GPU, and tolerance for a very deliberate pace', '2024-11-08 05:00:00+00'),
('Bladewright', 21.50, 'A crafting-focused RPG where you never fight; you forge for people who do, and they come back with the swords in various states of failure. Metallurgy is simulated deeply enough that bad steel actually fails under stress in the field. Reputation, commissions, and a war you only experience through returning customers.', 'rpg, simulation, crafting', 'singleplayer, crafting, story rich, economy, no combat', '6 GB RAM, any GPU; the forge physics are the only demanding bit', '2021-08-31 14:00:00+00'),
('Parallax Hostage', 17.99, 'A puzzle-platformer built around a camera you can detach and leave behind, creating two viewpoints that must both be satisfied to progress. Geometry that is solid from one angle is passable from another, and later levels demand you hold contradictory spatial models in your head. Around seven hours, ruthlessly clever.', 'puzzle, platformer, indie', 'singleplayer, difficult, minimalist, controller support, experimental', 'mid-range GPU for dual-view rendering; it is doing more work than it looks like', '2023-05-09 10:00:00+00'),
('Grease and Prayer', 12.50, 'A motorcycle restoration game with a full mechanical simulation and a road trip wrapped around it. Every part you fit affects handling on the long highway stretches between towns, and there is no parts shop that carries everything. Roughly eighteen hours, with a bike that ends up uniquely yours and probably slightly wrong.', 'simulation, adventure, racing', 'singleplayer, crafting, realistic, story rich, sandbox', 'mid-range PC; oil stains on the keyboard are your own responsibility', '2022-06-05 15:00:00+00'),
('Cold Open', 0.00, 'A free comedy adventure where you play a sketch writer with forty minutes of in-game time before a live broadcast and no finished script. You raid old drafts, bully cast members, and assemble a show from whatever survives. Every run produces a different broadcast, and the game performs it back to you at the end.', 'adventure, comedy, simulation', 'singleplayer, free to play, humor, short sessions, replayable', 'potato pc without gpu, which is also the budget of the fictional show', '2024-12-01 21:00:00+00'),
('Anchorhold', 35.99, 'A survival management game about an isolated monastery that shelters travelers during a decades-long winter. You decide who to admit, what to spend, and which vows to break to keep everyone alive. Time passes in seasons, characters age and die of ordinary causes, and the campaign spans a full generation.', 'strategy, survival, simulation', 'singleplayer, management, story rich, choices matter, historical', '8 GB RAM, modest GPU, and a willingness to be the reason someone froze', '2021-01-21 08:00:00+00'),
('The Long Commute', 0.00, 'A free two-hour driving game consisting of a single uninterrupted highway route at dusk, with a radio that plays talk shows written specifically for this game. Nothing chases you, nothing attacks, and there is no destination marker until the final twenty minutes. Most players report the ending lands harder than it has any right to.', 'adventure, driving, narrative', 'singleplayer, free to play, relaxing, atmospheric, story rich', 'potato pc without gpu; the dusk is baked into the textures, we cheated', '2024-01-05 18:00:00+00');
